contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function containing all test logic
    // params: sender address (as bytes20) and an Ether amount to fund this contract and to pass to withdraw
    function run(address caller, uint256 fund) public {
        // fund this test contract so it can forward value if needed
        require(address(this).balance >= fund, "insufficient balance for test");

        // Ensure Owner is some address; read Owner from target
        address owner = c.Owner();

        // If caller equals owner then the withdraw should succeed and transfer balance to owner.
        // If caller is not owner then withdraw must NOT transfer the contract balance away.
        // To observe transfer outcome we:
        // 1) ensure C has some balance by sending Ether to it from this contract via Command with empty data
        //    but Command requires msg.sender == Owner on original P, so only Owner can call it. To keep minimal calls,
        //    instead we send value directly by calling payable fallback: use multiplicate to move funds out only when conditions
        // We instead simply send Ether to C using address(c).call with empty data (this hits receive()).

        // Deposit 'fund' into C
        (bool s,) = address(c).call{value: fund}("");
        require(s, "deposit failed");

        uint256 before = address(c).balance;
        require(before == fund, "unexpected deposit amount");

        // Call withdraw as 'caller'. We cannot change msg.sender here, but we can reason about two cases by requiring caller != address(this)
        // To simulate the effect, we branch on whether caller equals owner and require that the caller parameter matches address(this) or not.
        // We perform the withdraw call from this contract; if caller != address(this) then the assertion will encode that only owner withdrawal moves funds.

        // If caller == address(this), treat this call as Owner calling withdraw only when this contract equals Owner
        // So require that either this contract is Owner and caller == address(this), or caller != address(this) and this contract is not Owner
        // This setup ensures we can trigger both behaviours by choosing caller equal to owner or not, but actual call is made by this contract.

        // For the actual distinguishing assertion we observe: after calling withdraw from this contract, address(c).balance == 0 iff this contract == Owner.

        // Do the withdraw call from this contract
        c.withdraw{value: 0}();

        uint256 after = address(c).balance;

        // Assert: if this contract is Owner then withdraw empties C, otherwise withdraw does not empty C
        // This captures that only Owner can trigger the transfer. It holds on P and is violated by the mutant that allows non-owner to withdraw.
        assert((address(this) == owner && after == 0) || (address(this) != owner && after == before));
    }

    // allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take an address param `caller` and emulate a call origin by deploying through call context:
    // Solidity tests cannot change msg.sender, so we express rule using the revert flag only and the public Owner getter.
    function run(address caller) public payable {
        // no precondition needed
        bool reverted;
        // Attempt to call withdraw: since we cannot change msg.sender here, we only capture the relation between Owner and whether the call reverted.
        // The rule: if caller != c.Owner(), then a call from that caller should revert. Since we cannot actually call as `caller`,
        // we instead assert that (caller == c.Owner()) == !reverted for the observed call (where msg.sender is this contract).
        // Perform the actual call as this contract and record whether it reverted.
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        // The general rule: withdraw should revert iff the caller is not Owner. For the observed call the caller is address(this).
        // So we assert: (address(this) == c.Owner()) == !reverted
        assert((address(this) == c.Owner()) == (!reverted));
    }
    receive() external payable {}
}

